DROP TABLE IF EXISTS order_transaction;

-- DROP SEQUENCE IF EXISTS order_transaction_order_transaction_id_seq;
-- CREATE SEQUENCE order_transaction_order_transaction_id_seq;


CREATE TABLE order_transaction (
  "order_transaction_id" int PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, -- SERIAL PRIMARY KEY,
  "order_id" int check ("order_id" > 0) NOT NULL,
  "kind" varchar(32) NOT NULL DEFAULT '',
  "gateway" varchar(64) NOT NULL DEFAULT '',
  "reference" varchar(191) NOT NULL DEFAULT '',
  "amount" decimal(15,4) NOT NULL DEFAULT 0.0000,
  "tax_amount" decimal(15,4) NOT NULL DEFAULT 0.0000,
  "currency" varchar(3) NOT NULL DEFAULT '',
  "status" varchar(32) NOT NULL DEFAULT '',
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
  -- PRIMARY KEY("order_transaction_id")
);

CREATE INDEX "order_id" ON order_transaction ("order_id");
